// LeetCode 636 — exclusive running time of each function on one CPU, from start/end logs.
// A log is "id:start:t" (begins at the start of tick t) or "id:end:t" (finishes at the END of tick t).
public static class ExclusiveTime {
    public static int[] Compute(int n, IList<string> logs) {
        var time = new int[n];
        var stack = new Stack<int>();            // functions currently running; the top one owns the CPU
        int prev = 0;                            // the first tick not yet charged to anyone
        foreach (string log in logs) {
            string[] p = log.Split(':');
            int id = int.Parse(p[0]), t = int.Parse(p[2]);
            if (p[1] == "start") {
                if (stack.Count > 0) time[stack.Peek()] += t - prev;   // the running function paused at t
                stack.Push(id);
                prev = t;
            } else {
                time[stack.Pop()] += t - prev + 1;                     // "end" includes tick t itself
                prev = t + 1;
            }
        }
        return time;
    }
}
```

